mapper.select:
SELECT EXISTS (
  SELECT 1
    FROM new_contract.code_definition
   WHERE code_group = #{codeGroup}
     AND code_field = #{codeField}
     AND code_value = #{code}
     AND active_flag = 'Y'
     AND effective_from <= CURRENT_DATE
     AND (effective_to IS NULL OR effective_to >= CURRENT_DATE)
)
